

import typing

from ..core.client_wrapper import AsyncClientWrapper, SyncClientWrapper
from ..core.request_options import RequestOptions
from ..types.address import Address
from ..types.address_siacoin_elements_response import AddressSiacoinElementsResponse
from ..types.address_siafund_elements_response import AddressSiafundElementsResponse
from ..types.balance import Balance
from ..types.event import Event
from .raw_client import AsyncRawAddressesClient, RawAddressesClient


class AddressesClient:
    def __init__(self, *, client_wrapper: SyncClientWrapper):
        self._raw_client = RawAddressesClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> RawAddressesClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        RawAddressesClient
        """
        return self._raw_client

    def get_address_balance(self, addr: Address, *, request_options: typing.Optional[RequestOptions] = None) -> Balance:
        """
        Parameters
        ----------
        addr : Address
            Sia address (unlock hash).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Balance
            Aggregated siacoin and siafund balance for the address.

        Examples
        --------
        from fern import FernApi

        client = FernApi()
        client.addresses.get_address_balance(
            addr="addr",
        )
        """
        _response = self._raw_client.get_address_balance(addr, request_options=request_options)
        return _response.data

    def get_address_events(
        self,
        addr: Address,
        *,
        offset: typing.Optional[int] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> typing.List[Event]:
        """
        Returns confirmed events affecting the supplied address.

        Parameters
        ----------
        addr : Address
            Sia address (unlock hash).

        offset : typing.Optional[int]
            Number of items to skip.

        limit : typing.Optional[int]
            Maximum number of items to return (default 1000).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        typing.List[Event]
            Events involving the address.

        Examples
        --------
        from fern import FernApi

        client = FernApi()
        client.addresses.get_address_events(
            addr="addr",
        )
        """
        _response = self._raw_client.get_address_events(
            addr, offset=offset, limit=limit, request_options=request_options
        )
        return _response.data

    def get_address_events_unconfirmed(
        self, addr: Address, *, request_options: typing.Optional[RequestOptions] = None
    ) -> typing.List[Event]:
        """
        Returns unconfirmed events generated by unconfirmed transactions that reference the address.

        Parameters
        ----------
        addr : Address
            Sia address (unlock hash).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        typing.List[Event]
            Unconfirmed events touching the address.

        Examples
        --------
        from fern import FernApi

        client = FernApi()
        client.addresses.get_address_events_unconfirmed(
            addr="addr",
        )
        """
        _response = self._raw_client.get_address_events_unconfirmed(addr, request_options=request_options)
        return _response.data

    def get_address_siacoin_outputs(
        self,
        addr: Address,
        *,
        tpool: typing.Optional[bool] = None,
        offset: typing.Optional[int] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AddressSiacoinElementsResponse:
        """
        Parameters
        ----------
        addr : Address
            Sia address (unlock hash).

        tpool : typing.Optional[bool]
            Include unconfirmed txpool outputs.

        offset : typing.Optional[int]
            Number of items to skip.

        limit : typing.Optional[int]
            Maximum number of items to return (default 1000).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AddressSiacoinElementsResponse
            Unspent siacoin outputs owned by the address.

        Examples
        --------
        from fern import FernApi

        client = FernApi()
        client.addresses.get_address_siacoin_outputs(
            addr="addr",
        )
        """
        _response = self._raw_client.get_address_siacoin_outputs(
            addr, tpool=tpool, offset=offset, limit=limit, request_options=request_options
        )
        return _response.data

    def get_address_siafund_outputs(
        self,
        addr: Address,
        *,
        tpool: typing.Optional[bool] = None,
        offset: typing.Optional[int] = None,
        limit: typing.Optional[int] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> AddressSiafundElementsResponse:
        """
        Parameters
        ----------
        addr : Address
            Sia address (unlock hash).

        tpool : typing.Optional[bool]
            Include unconfirmed txpool outputs.

        offset : typing.Optional[int]
            Number of items to skip.

        limit : typing.Optional[int]
            Maximum number of items to return (default 1000).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        AddressSiafundElementsResponse
            Unspent siafund outputs owned by the address.

        Examples
        --------
        from fern import FernApi

        client = FernApi()
        client.addresses.get_address_siafund_outputs(
            addr="addr",
        )
        """
        _response = self._raw_client.get_address_siafund_outputs(
            addr, tpool=tpool, offset=offset, limit=limit, request_options=request_options
        )
        return _response.data


class AsyncAddressesClient:
    def __init__(self, *, client_wrapper: AsyncClientWrapper):
        self._raw_client = AsyncRawAddressesClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> AsyncRawAddressesClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        AsyncRawAddressesClient
        """
        return self._raw_client

    async def get_address_balance(
        self, addr: Address, *, request_options: typing.Optional[RequestOptions] = None
    ) -> Balance:
        """
        Parameters
        ----------
        addr : Address
            Sia address (unlock hash).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Balance
            Aggregated siacoin and siafund balance for the address.

        Examples
        --------
        import asyncio

        from fern import AsyncFernApi

        client = AsyncFernApi()


        async def main() -> None:
            await client.addresses.get_address_balance(
                addr="addr",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.get_address_balance(addr, request_options=request_options)
        return _response.data

